concepts.code_exemple:
SELECT produit, ville
FROM ventes;

SELECT *
FROM ventes
LIMIT 5;

SELECT *
FROM ventes
WHERE produit = 'Cacao';

SELECT produit, quantite
FROM ventes
WHERE quantite > 150 AND ville = 'Abidjan';

SELECT produit,
       quantite * prix_unitaire AS montant
FROM ventes;

SELECT * FROM ventes
WHERE ville IN ('Daloa', 'Man');

SELECT * FROM ventes
WHERE quantite BETWEEN 100 AND 200;

SELECT DISTINCT ville FROM ventes
WHERE ville LIKE 'B%';

SELECT COUNT(*) AS nb_ventes FROM ventes;

SELECT DISTINCT produit FROM ventes;

SELECT COUNT(DISTINCT ville) AS nb_villes
FROM ventes;
